Read: `src/auth/session.ts`, `src/auth/users.ts`, `src/api/routes.ts`, `test/session.test.ts`, plus `package.json`/`tsconfig.json`.

Both new files fall under existing `include` globs (`src/auth/**/*.ts`, `test/**/*.ts`), so no config or registry changes are needed. `login` (src/api/routes.ts:11) starts a session with a plain `createSession(user.id)`, so "exactly the way login does" = `createSession(existing.userId)`.

## Plan

**1. New file `src/auth/refresh.ts`**

```ts
import { createSession, getSession, revokeSession, type Session } from "./session.ts";

/** Rotate a session token: revoke the current session and issue a fresh one for the same user. */
export function refreshSession(token: string): Session | undefined {
  const current = getSession(token);
  if (!current) return undefined;
  revokeSession(token);
  return createSession(current.userId);
}
```

**2. New file `test/refresh.test.ts`** (node:test + node:assert/strict, `beforeEach(resetSessions)`, matching test/session.test.ts style)

```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { createSession, getSession, resetSessions, revokeSession } from "../src/auth/session.ts";
import { refreshSession } from "../src/auth/refresh.ts";

beforeEach(() => resetSessions());

test("refreshSession returns undefined for an unknown token", () => {
  assert.equal(refreshSession("nope"), undefined);
});

test("refreshSession revokes the old token and issues a new session for the same user", () => {
  const old = createSession("u_1");
  const fresh = refreshSession(old.token);
  assert.ok(fresh);
  assert.equal(fresh.userId, "u_1");
  assert.notEqual(fresh.token, old.token);
});

test("refreshSession leaves the new session usable", () => {
  const old = createSession("u_2");
  const fresh = refreshSession(old.token)!;
  assert.equal(getSession(old.token), undefined);
  assert.equal(getSession(fresh.token)?.userId, "u_2");
});

test("refreshSession on an already revoked token returns undefined", () => {
  const s = createSession("u_3");
  assert.equal(revokeSession(s.token), true);
  assert.equal(refreshSession(s.token), undefined);
});
```

Tests deliberately avoid asserting on `createdAt` (can tie within the same millisecond). No files written yet — say the word and I'll create them, then run `npm test` and `npm run typecheck`.
